const { useState } = React;

function App() {
  const [fullName, setFullName] = useState("");
  const [address, setAddress] = useState("");
  const [city, setCity] = useState("");
  const [zipCode, setZipCode] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("Card");
  const [error, setError] = useState("");
  const [orderPlaced, setOrderPlaced] = useState(false);

  const items = [
    { name: "Linen shirt", price: 40 },
    { name: "Straw hat", price: 14 },
  ];

  const total = items.reduce((acc, item) => acc + item.price, 0);

  function handlePlaceOrder() {
    if (!fullName.trim() || !address.trim() || !city.trim() || !zipCode.trim()) {
      setError("Please fill in all shipping fields.");
    } else {
      setError("");
      setOrderPlaced(true);
    }
  }

  if (orderPlaced) {
    return (
      <>
        <style>{`
          * {
            box-sizing: border-box;
          }
          body {
            margin: 0;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: #fefbf6;
            color: #222;
          }
          main {
            max-width: 720px;
            margin: 2rem auto;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 1rem;
          }
          h1 {
            font-weight: 600;
            font-size: 1.8rem;
            margin-bottom: 1rem;
            font-family: 'Comic Sans MS', cursive, sans-serif;
            color: #222;
          }
          p {
            font-family: 'Comic Sans MS', cursive, sans-serif;
            font-size: 1.1rem;
            color: #222;
            max-width: 480px;
            text-align: center;
          }
          button {
            background: #222;
            color: #fff;
            border: none;
            border-radius: 0.6rem;
            padding: 0.6rem 1rem;
            font-family: 'Comic Sans MS', cursive, sans-serif;
            font-size: 1rem;
            cursor: pointer;
            transition: background-color 0.2s ease;
          }
          button:hover {
            background: #444;
          }
        `}</style>
        <main>
          <h1>Order Confirmed</h1>
          <p>Thank you, <strong>{fullName}</strong>! Your order has been placed successfully.</p>
          <p>We will ship your items to:</p>
          <address style={{fontStyle: 'normal', textAlign: 'center', fontFamily: "'Comic Sans MS', cursive, sans-serif"}}>
            {address}<br />
            {city}, {zipCode}
          </address>
          <p>Payment method: <strong>{paymentMethod}</strong></p>
          <button onClick={() => window.location.reload()} aria-label="Place another order">Place another order</button>
        </main>
      </>
    );
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          background: #fefbf6;
          color: #222;
        }
        main {
          max-width: 720px;
          margin: 2rem auto;
          padding: 1rem;
          display: flex;
          gap: 2rem;
          flex-wrap: wrap;
        }
        h1 {
          font-weight: 600;
          font-size: 1.8rem;
          margin-bottom: 1rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          color: #222;
        }
        h2 {
          font-weight: 600;
          font-size: 1.2rem;
          margin-bottom: 0.5rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          color: #222;
        }
        form {
          flex: 1 1 320px;
          display: flex;
          flex-direction: column;
          gap: 1.5rem;
        }
        fieldset {
          border: none;
          padding: 0;
          margin: 0;
        }
        legend {
          font-family: 'Comic Sans MS', cursive, sans-serif;
          font-weight: 600;
          font-size: 1.1rem;
          margin-bottom: 0.5rem;
          color: #222;
        }
        label {
          display: block;
          font-size: 0.9rem;
          margin-bottom: 0.25rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          color: #222;
        }
        input[type=text] {
          width: 100%;
          padding: 0.5rem 0.6rem;
          border: 2px solid #999;
          border-radius: 0.4rem;
          font-size: 1rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          transition: border-color 0.2s ease;
        }
        input[type=text]:focus {
          border-color: #555;
          outline: none;
        }
        .shipping-row {
          display: flex;
          gap: 1rem;
        }
        .shipping-row > div {
          flex: 1;
        }
        .payment-options {
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          font-size: 1rem;
          color: #222;
        }
        .payment-options label {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          cursor: pointer;
        }
        input[type=radio] {
          accent-color: #222;
          width: 1.2rem;
          height: 1.2rem;
          cursor: pointer;
        }
        aside {
          flex: 0 0 240px;
          border: 2px solid #222;
          border-radius: 0.6rem;
          padding: 1rem 1.2rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          color: #222;
          background: #fff;
          height: fit-content;
          display: flex;
          flex-direction: column;
          justify-content: space-between;
        }
        .order-items {
          margin-bottom: 1rem;
          padding-bottom: 0.5rem;
          border-bottom: 1px solid #ccc;
          font-size: 1rem;
        }
        .order-items li {
          margin-bottom: 0.3rem;
          list-style-type: disc;
          padding-left: 1.2rem;
        }
        .order-total {
          font-weight: 600;
          margin-bottom: 1rem;
          font-size: 1.1rem;
        }
        button {
          background: #222;
          color: #fff;
          border: none;
          border-radius: 0.6rem;
          padding: 0.6rem 1rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          font-size: 1rem;
          cursor: pointer;
          transition: background-color 0.2s ease;
        }
        button:hover {
          background: #444;
        }
        .error {
          color: #b00020;
          font-weight: 600;
          margin-top: -1rem;
          margin-bottom: 1rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          font-size: 0.9rem;
        }
      `}</style>
      <main>
        <form onSubmit={e => e.preventDefault()} aria-label="Checkout form">
          <h1>Checkout</h1>
          <fieldset>
            <legend>Shipping</legend>
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              value={fullName}
              onChange={e => setFullName(e.target.value)}
              aria-required="true"
            />
            <label htmlFor="address">Address</label>
            <input
              id="address"
              type="text"
              value={address}
              onChange={e => setAddress(e.target.value)}
              aria-required="true"
            />
            <div className="shipping-row">
              <div>
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={city}
                  onChange={e => setCity(e.target.value)}
                  aria-required="true"
                />
              </div>
              <div>
                <label htmlFor="zipCode">Zip code</label>
                <input
                  id="zipCode"
                  type="text"
                  value={zipCode}
                  onChange={e => setZipCode(e.target.value)}
                  aria-required="true"
                />
              </div>
            </div>
          </fieldset>

          <fieldset>
            <legend>Payment</legend>
            <div className="payment-options">
              <label htmlFor="card">
                <input
                  type="radio"
                  id="card"
                  name="payment"
                  value="Card"
                  checked={paymentMethod === "Card"}
                  onChange={e => setPaymentMethod(e.target.value)}
                />
                Card
              </label>
              <label htmlFor="paypal">
                <input
                  type="radio"
                  id="paypal"
                  name="payment"
                  value="PayPal"
                  checked={paymentMethod === "PayPal"}
                  onChange={e => setPaymentMethod(e.target.value)}
                />
                PayPal
              </label>
              <label htmlFor="cod">
                <input
                  type="radio"
                  id="cod"
                  name="payment"
                  value="Cash on delivery"
                  checked={paymentMethod === "Cash on delivery"}
                  onChange={e => setPaymentMethod(e.target.value)}
                />
                Cash on delivery
              </label>
            </div>
          </fieldset>
          {error && (
            <p className="error" role="alert">
              {error}
            </p>
          )}
        </form>

        <aside aria-label="Order summary">
          <h2>order summary</h2>
          <ul className="order-items">
            {items.map((item, i) => (
              <li key={i}>
                {item.name} <span style={{ float: "right" }}>${item.price}</span>
              </li>
            ))}
          </ul>
          <p className="order-total">Total ${total}</p>
          <button onClick={handlePlaceOrder} aria-label="Place order">
            Place order
          </button>
        </aside>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

